import pkg_resources
import logging
import re
import os
import time
import shutil
import zipfile
from .ttitrace import TtiTrace
from .executor import AaShellExecutor
from .xml import LocalXML


class TtiTraceServer(TtiTrace):
    KEY_PARAMS = {}

    def __init__(self, host_ip, ssh_username, ssh_password, ssh_prompt, ssh_port, stream_path,
                 tracer_path, ip_addr, timeout, log_path, sw_version, cells_sw_type):
        self._log = logging.getLogger(__name__)
        stream_path = None
        tracer_path = None
        self.tool_base_dir = pkg_resources.resource_filename(__name__, "resources")
        self._server_path = "{}/TtiTraceServer".format(self.tool_base_dir)
        self._client_path = "{}/TTITraceStreamingClient".format(self._server_path)
        self._cmptool = os.path.join(self.tool_base_dir, "getcellmapping")
        self._extract_ttitrace_server()
        super(TtiTraceServer, self).__init__(host_ip, ssh_username, ssh_password, ssh_prompt,
                                             ssh_port, stream_path, tracer_path, ip_addr,
                                             timeout, log_path, sw_version, cells_sw_type)
        self._server_settings_file = "settings.xml"
        self._client_settings_file = "client_settings.xml"
        self._host_ip = host_ip
        self._ip_addr = ip_addr
        self._port = None
        self._is_server_model = True
        self._cell_mapping_prefix = {}
        self._clean_server_path()

    def start_tti_stream(self, core, param):
        """start tti stream"""
        lncel_list = self._convert_all_core_to_lncel(core)
        param = self._set_default_value(param)
        self._mapping_prefix_to_cell(lncel_list, param)
        if self._server_started:
            self._log.info("Server already started, optional parameters will be ignore except prefix.")
        else:
            self._generated_settings_and_start_server(param)
            self._server_started = True
        for lncel in lncel_list:
            self._start_ttitrace_streaming(lncel)
        self._started_lncel = lncel_list

    def stop_tti_stream(self, lrc=None):
        """stop tti stream"""
        if lrc is None:
            out = []
            for cellid in self._started_lncel:
                ret = self._stop_and_get_dat_file(cellid)
                out.extend(ret)
            self._log_files.extend(out)
        else:
            lncel = self._conver_lrc_to_lncel(lrc)
            out = self._stop_and_get_dat_file(lncel)
            self._log_files.extend(out)
        return out

    def stop_tti_stream_and_convert_to_text(self, nb, ext='txt', lrc=None):
        """stop tti and decode dat file, if lrc is None, it will decode all dat file for all started. """
        dat_files = self.stop_tti_stream(lrc)
        return list(filter(None, [self.convert_dat_to_text(source=file, destination=None, nb=nb, ext=ext) for file in
                                  dat_files]))

    def convert_dat_to_text(self, source, destination, nb, ext='txt'):
        """decode dat"""
        if not self._is_dat_file_size_greater_than_1024(source):
            self._log.info("{} size is less than 1024, will not be decoded".format(source))
            return
        destination = destination or "{}.{}".format(source, ext)
        cmd = 'cd {} && {} --decode {} --output {} {}'.format(self._log_path, self._tracer_path, source, destination,
                                                              '-nb' if nb else '')
        out = self._executor.run(cmd.strip())
        output = self._validate_ouput_file_created(out)
        if output:
            self._log_files.append(output)
        return output

    def get_tti_dl_node(self, lcr=None):
        """get tti dl node by lcr"""
        return self._get_node(lcr, table='MACDLTTI')

    def get_tti_ul_node(self, lcr=None):
        """get tti ul node by lcr"""
        return self._get_node(lcr, table='MACULTTI')

    def _clean_server_path(self):
        kill_proc = "timeout 5 sudo kill -9 $(ps -ef|grep " + self._stream_path['server'] +\
                    "|grep -v grep|awk '{print $2}') 1>/dev/null 2>&1"
        rm_settings = "sudo rm {}/{} -rf; sudo rm {}/{} -rf".format(self._server_path, self._server_settings_file,
                                                                    self._client_path, self._client_settings_file)
        rm_dat = "sudo rm {}/tti_stream_cell* -rf".format(self._server_path)
        rm_log = "sudo rm {}/logs -rf;sudo rm {}/*_WriteResponseFile_* -rf".format(self._server_path, self._client_path)
        self._executor.execute_command(kill_proc)
        self._executor.execute_command(rm_settings)
        self._executor.execute_command(rm_dat)
        self._executor.execute_command(rm_log)

    def _extract_ttitrace_server(self):
        server_zip_path = os.path.join(self.tool_base_dir, "TtiTraceServer.zip")
        self._log.info(server_zip_path)
        with zipfile.ZipFile(server_zip_path, 'r') as zip_ref:
            zip_ref.extractall(self.tool_base_dir)

    def _generated_settings_and_start_server(self, param):
        self._generated_ttitrace_server_setting()
        self._change_filesize_in_server_setting_file(param)
        self._generated_ttitrace_client_setting()
        self._start_ttitrace_server()

    def _mapping_prefix_to_cell(self, cell, param):
        param.setdefault('prefix', '{}/{}'.format(self._log_path, 'tti'))

        for id in cell:
            self._cell_mapping_prefix[id] = param['prefix'].split("/")[-1] if "/" in param['prefix'] else param['prefix']

    def _get_lncellid_by_core(self, core, cell_info_table):
        for info in cell_info_table.splitlines():
            if core in info.split():
                return info.split()[1]

    def _convert_all_core_to_lncel(self, core):
        lnCelIds = []
        cell_info_table = self._get_cell_info_table()
        self._log.debug(cell_info_table)
        for one_core in core.split(','):
            lncel = self._get_lncellid_by_core(one_core, cell_info_table)
            lnCelIds.append(lncel)
        return sorted(set(lnCelIds), key=lnCelIds.index)

    def _conver_lrc_to_lncel(self, lrc):
        cell_info_table = self._get_cell_info_table()
        for info in cell_info_table.splitlines():
            if info.split()[0] == lrc:
                return info.split()[1]

    def _start_ttitrace_server(self):
        start_cmd = "cd {} && ./{} --daemon".format(self._server_path, self._stream_path['server'])
        self._executor.write_to_shell('{}\n'.format(start_cmd))
        self._executor.read_until('TTI Trace Server at your service, listening on port')

    def _start_ttitrace_streaming(self, cellid):
        self._delete_client_log_file()
        sub_cmd = 'cd {} && ./{} --params --command "start"'.format(self._client_path, self._stream_path['client'])
        self._log.debug(self._cell_mapping_prefix)
        start_cmd = '{} --cellID {} --name {}'.format(sub_cmd, cellid, self._cell_mapping_prefix[cellid])
        self._executor.execute_command('{}\n'.format(start_cmd))
        self._check_command_execute_result(op='start')

    def _check_command_execute_result(self, op='start'):
        out = self._executor.execute_command("ls -la {}|grep WriteResponseFile".format(self._client_path))
        if 'WriteResponseFile' not in out:
            raise Exception("There is no command execution log, execution reslut is unknow.")
        content = self._executor.execute_command('cat {}/{}'.format(self._client_path, out.split()[-1]))
        self._get_tool_log_to_log_path('{}/{}'.format(self._client_path, out.split()[-1]))
        self._get_tool_log_to_log_path('{}/logs/{}'.format(self._server_path, 'TTITrace_*.log'))
        if "<error_code>0</error_code>" not in content:
            raise Exception("Streamming do not {} successfully.".format(op))

    def _delete_client_log_file(self):
        self._executor.execute_command("sudo rm {}/*_WriteResponseFile_* -rf".format(self._client_path))

    def _generated_ttitrace_server_setting(self):
        server_setting_cmd = "cd {} && ./{} --config --enb {} {}".format(self._server_path, self._stream_path['server'],
                                                                         self._ip_addr, self._port)
        self._executor.write_to_shell('{}\n'.format(server_setting_cmd))
        self._is_setting_file_generated(self._server_path, self._server_settings_file)

    def _generated_ttitrace_client_setting(self):
        client_setting_cmd = "cd {} && ./{} --gen_default_settings".format(self._client_path, self._stream_path['client'])
        self._executor.write_to_shell('{}\n'.format(client_setting_cmd))
        self._is_setting_file_generated(self._client_path, self._client_settings_file)

    def _is_setting_file_generated(self, file_path, file_name):
        time.sleep(1)
        for n in range(0, 6):
            out = self._executor.execute_command("ls -la {}|grep {}".format(file_path, file_name))
            if file_name in out:
                self._executor.execute_command('cat {}/{}'.format(file_path, file_name))
                return
            self._log.warning("Generate settings.xml fail. {}".format(n))
            time.sleep(0.5)
        raise Exception("Generate {} fail, file is not exist.".format(file_name))

    def _change_filesize_in_server_setting_file(self, param):
        if 'filesize' in param:
            file_size = param['filesize']
            self._modify_xml_value('./dat_file_size_mb_limit', file_size)

    def _copy_setting_file_to_local(self, file_name):
        tmp_path = "/tmp/ttiserver_{}".format(time.strftime('%Y%m%d%H%M%S', time.localtime(time.time())))
        os.makedirs(tmp_path)
        self._executor.get_file(file_name, os.path.join(tmp_path, os.path.basename(file_name)))
        return os.path.join(tmp_path, os.path.basename(file_name))

    def _modify_xml_value(self, key, value):
        xml_inst = LocalXML()
        setting_path = '{}/{}'.format(self._server_path, self._server_settings_file)
        local_set_path = self._copy_setting_file_to_local(setting_path)
        setting_parse = xml_inst.parse_xml(local_set_path)
        xml_inst.set_element_text(setting_parse, value, xpath=key)
        xml_inst.save_xml(setting_parse, local_set_path)
        self._executor.put_file(local_set_path, setting_path)
        shutil.rmtree(os.path.dirname(local_set_path))

    def _execute_tti_stream_cmd(self, cmd, except_str=None):
        out = self._executor.execute_command("{}\n".format(cmd.strip()))
        if except_str and except_str not in out:
            raise Exception('start {} fail, there is no [{}] in return.'.format(cmd, except_str))

    def _stop_and_get_dat_file(self, lncel):
        self._delete_client_log_file()
        sub_cmd = 'cd {} && ./{} --params --command "stop"'.format(self._client_path, self._stream_path['client'])
        stop_cmd = '{} --cellID {} --name {}'.format(sub_cmd, lncel, self._cell_mapping_prefix[lncel])
        self._execute_tti_stream_cmd(stop_cmd)
        self._check_command_execute_result(op='stop')
        return self._get_created_dat_file(lncel)

    def _get_created_dat_file(self, lncel):
        cmd = 'ls {}/tti_stream_cell_{}_{}_*.dat'.format(self._server_path, self._cell_mapping_prefix[lncel], lncel)
        out = self._executor.execute_command(cmd)
        self._log.debug(out)
        return self._extract_dat_files_from_output(out, lncel)

    def _extract_dat_files_from_output(self, out, lncel):
        dat_files = self._get_accurate_dat_file(out, lncel)
        if not len(dat_files):
            raise Exception('No Dat File was created.')
        else:
            return self._attach_log_path_to_output(dat_files)

    def _get_accurate_dat_file(self, out, lncel):
        files_list = out.split()
        target_dat = []
        for dat in files_list:
            destination = '{}/{}'.format(self._log_path, os.path.basename(dat))
            self._move_dat_file_from_tool_path_to_log_path(dat, destination)
            target_dat.append(destination)
        return target_dat

    def _move_dat_file_from_tool_path_to_log_path(self, dat, destination):
        self._executor.execute_command('mv {} {}'.format(dat, destination))

    def _set_default_value(self, param):
        param.setdefault('ip_addr', self._ip_addr)
        param.setdefault('port', 15003)
        param.setdefault('prefix', 'tti')
        param.setdefault('filesize', '100')
        self._log.debug(param)
        self._port = param['port']
        return param

    def _get_default_stream_path(self):
        stream_path = {'server': 'TTITraceServer.linux',
                       'client': 'TTITraceStreamingClient.linux'}
        return stream_path

    def _get_default_tracer_path(self):
        tracer_name = 'tti_trace_parser_wmp-linux.exe'
        tracer_path = self._find_tracer_path(tracer_name, '/opt/TtiTracer')
        return tracer_path

    def _find_tracer_path(self, name, path):
        try:
            return self._executor.run('find {} -name {}'.format(path, name)).split()[0]
        except Exception:
            raise Exception('Default Ttitracer not found.')

    def _ensure_ttitracers_are_executable(self):
        self._executor.run('sudo chmod u+x {}/{}'.format(self._server_path, self._stream_path['server']))
        self._executor.run('sudo chmod u+x {}/{}'.format(self._client_path, self._stream_path['client']))
        self._executor.run('sudo chmod u+x {}'.format(self._tracer_path))
        self._executor.run("sudo chmod u+x {}".format(self._cmptool))

    def _get_node(self, lcr, table):
        cell_info_table = self._get_cell_info_table()
        lcr = lcr or self._get_first_local_cell_resource_id(cell_info_table)
        column = self._get_table_column(cell_info_table, table)
        return self._extract_node(cell_info_table, lcr, column)

    def _get_cell_info_table(self):
        out = self._get_cell_mapping()
        self._log.debug(out)
        cell_info_table = self._extract_table_from_output(out)
        return cell_info_table

    def _extract_table_from_output(self, out):
        try:
            return re.search(r'(lcr lnCel.*\n[\w\s.-]+)\n', out, re.MULTILINE).group(1)
        except Exception:
            raise Exception('Table not found.')

    def _get_first_local_cell_resource_id(self, cell_info_table):
        cells = cell_info_table.splitlines()
        return cells[1].split()[0]

    def _get_table_column(self, cell_info_table, table):
        cells = cell_info_table.splitlines()
        tables = cells[0].split()
        for index in range(0, len(tables)):
            if table == tables[index]:
                return index
        raise Exception("{} did not match any table name".format(table))

    def _extract_node(self, cell_info_table, lcr, node):
        cells = cell_info_table.splitlines()
        for cell in cells:
            if cell.split()[0] == lcr:
                return cell.split()[node][:10] if len(cell.split()[node]) >= 10 else cell.split()[node][:6]
        raise Exception('{} did not match any local cell resource'.format(lcr))

    def _get_cell_mapping(self):
        return self._executor.execute_command("sudo {} {} {}".format(self._cmptool, self._ip_addr, 15007))

    def _get_rromexe_address(self, proc_info):
        ret = proc_info.split("node:")
        for i in ret:
            if "RROMexe" in i:
                return i.strip().split()[0]

    def _execute_aashell_command(self, command):
        aashell = AaShellExecutor(self._ip_addr, 15007)
        try:
            aashell.connect()
            aashell.execute_command(command)
            return aashell.read_until_regexp()
        finally:
            aashell.close()

    def _is_dat_file_size_greater_than_1024(self, dat):
        out = self._executor.execute_command("wc -c {}".format(dat))
        size = int(out.split()[0].strip())
        return False if size < 1024 else True

    def _validate_ouput_file_created(self, out):
        lines = out.splitlines()
        p = re.compile(r'Creating ASCII File (\S+)')
        for line in lines:
            m = p.match(line)
            if m:
                return m.group(1)
        return ''

    def _get_tool_log_to_log_path(self, tool_log):
        self._executor.get_file(tool_log, os.path.join(self._log_path, 'TTITraceRunLog/'))
